LOG = "ping-pongings/knowledge-base/log.jsonl"
template_keys = {}
if os.path.exists(LOG):
    with open(LOG) as f:
        lines = [l for l in f if l.strip()]
    if lines:
        template_keys = json.loads(lines[-1])

existing_urls = set()
if os.path.exists(LOG):
    with open(LOG) as f:
        for l in f:
            l = l.strip()
            if not l: continue
            try:
                e = json.loads(l)
                u = e.get("url") or e.get("doi") or ""
                if u: existing_urls.add(u)
            except: pass

added = 0
with open(LOG, "a") as f:
    for p in PAPERS:
        if p["url"] in existing_urls or p["doi"] in existing_urls:
            continue
        entry = dict(template_keys)
        entry["source"] = "academic"
        entry["title"] = p["title"]
        entry["url"] = p["url"]
        entry["doi"] = p["doi"]
        entry["year"] = p["year"]
        entry["summary"] = p["abstract"]
        for k in ("sentiment", "catalyst", "xrp_relevance", "one_line", "distilled"):
            if k in entry:
                entry[k] = None if k != "distilled" else False
        f.write(json.dumps(entry) + "\n")
        added += 1

print(f"Appended {added} academic entries to {LOG}")
